package org.joda.time;

import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.Locale;
import org.joda.convert.FromString;
import org.joda.convert.ToString;
import org.joda.time.base.BaseDateTime;
import org.joda.time.chrono.ISOChronology;
import org.joda.time.field.AbstractReadableInstantFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MutableDateTime#addMonths
 */
public class MutableDateTime_addMonths_TriageGen0Test {

    @Test
    public void testAddPositiveMonths() {
        // Start at 2023-01-15
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(3);

        assertEquals(2023, dt.getYear());
        assertEquals(4, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddNegativeMonths() {
        // Start at 2023-05-15
        MutableDateTime dt = new MutableDateTime(2023, 5, 15, 10, 0, 0, 0);
        dt.addMonths(-2);

        assertEquals(2023, dt.getYear());
        assertEquals(3, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddZeroMonths() {
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0);
        dt.addMonths(0);

        assertEquals(2023, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsCrossingYearBoundary() {
        // Start at 2023-11-15
        MutableDateTime dt = new MutableDateTime(2023, 11, 15, 10, 0, 0, 0);
        dt.addMonths(3);

        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsCrossingCenturyBoundary() {
        // Start at 1999-12-15
        MutableDateTime dt = new MutableDateTime(1999, 12, 15, 10, 0, 0, 0);
        dt.addMonths(1);

        assertEquals(2000, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(15, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsEndOfMonthAdjustment() {
        // Jan 31st + 1 month should be Feb 28th or 29th (depending on leap year)
        MutableDateTime dt = new MutableDateTime(2023, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);

        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsLeapYearAdjustment() {
        // Jan 31st 2024 (Leap Year) + 1 month -> Feb 29th
        MutableDateTime dt = new MutableDateTime(2024, 1, 31, 10, 0, 0, 0);
        dt.addMonths(1);

        assertEquals(2024, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(29, dt.getDayOfMonth());
    }

    @Test
    public void testAddLargeNumberOfMonths() {
        // Start at 2023-01-01
        MutableDateTime dt = new MutableDateTime(2023, 1, 1, 10, 0, 0, 0);
        // 120 months = 10 years
        dt.addMonths(120);

        assertEquals(2033, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddMonthsWithDifferentTimeZones() {
        // Testing that the operation respects the chronology/zone of the instance
        DateTimeZone zone = DateTimeZone.forID("America/New_York");
        MutableDateTime dt = new MutableDateTime(2023, 1, 15, 10, 0, 0, 0, zone);
        dt.addMonths(1);

        assertEquals(2023, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(zone, dt.getZone());
    }
}
